const cloudDb=window.supabase.createClient('https://lcycxklnvtccervyuoee.supabase.co','sb_publishable_GwKb4zzZQlLeLCbo_DjqNg_7V0n4v_l');
async function loadCloudSettings(){const {data}=await cloudDb.from('store_settings').select('*');for(const row of data||[]){const form=row.key==='campaign'?campaignForm:row.key==='homepage'?homepageForm:null;if(!form)continue;Object.entries(row.value).forEach(([key,value])=>{const field=form.elements[key];if(field)field.type==='checkbox'?field.checked=value:field.value=value});form.dispatchEvent(new Event('input',{bubbles:true}))}}
async function saveCloudSetting(key,form,note){const value=Object.fromEntries(new FormData(form));const {error}=await cloudDb.from('store_settings').upsert({key,value});note.textContent=error?`Error: ${error.message}`:'Guardado en Supabase y listo para la tienda.'}
campaignForm?.addEventListener('submit',()=>saveCloudSetting('campaign',campaignForm,document.querySelector('#campaignNote')));
homepageForm?.addEventListener('submit',()=>saveCloudSetting('homepage',homepageForm,document.querySelector('#homepageNote')));
warrantyForm?.addEventListener('submit',async()=>{const fields=warrantyForm.elements,soldAt=fields[4].value;if(!soldAt)return;const expires=new Date(soldAt);expires.setMonth(expires.getMonth()+6);const {error}=await cloudDb.from('warranties').insert({model:fields[0].value,serial:fields[1].value,buyer_name:fields[2].value,contact:fields[3].value,sold_at:soldAt,expires_at:expires.toISOString().slice(0,10),note:fields[5].value});document.querySelector('#warrantyNote').textContent=error?`Error: ${error.message}`:'Garantía guardada en Supabase.';if(!error)warrantyForm.reset()});
loadCloudSettings();
